{"content": "# -*- coding: utf-8 -*-
import sys, re, html, urllib.parse, subprocess, os, tempfile

UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"

def fetch(url, referer="https://www.so.com/"):
    fd, path = tempfile.mkstemp(suffix=".html"); os.close(fd)
    args = ["curl", "-sL", "-m", "35", "-A", UA,
            "-H", "Accept-Language: zh-CN,zh;q=0.9",
            "-H", "Referer: " + referer, url, "-o", path]
    subprocess.run(args, capture_output=True)
    try:
        with open(path, "rb") as f:
            return f.read().decode("utf-8", "ignore")
    finally:
        try: os.remove(path)
        except: pass

def txt(t):
    t = re.sub(r"<(script|style|noscript)[^>]*>.*?</\1>", " ", t, flags=re.S|re.I)
    t = re.sub(r"<br\s*/?>", "\n", t, flags=re.I)
    t = re.sub(r"</(p|div|li|tr|h\d)>", "\n", t, flags=re.I)
    t = re.sub(r"<[^>]+>", " ", t)
    t = html.unescape(t)
    out = []
    for line in t.split("\n"):
        line = re.sub(r"[ \t\r\f\v]+", " ", line).strip()
        if line: out.append(line)
    return "\n".join(out)

def search(q, n=15):
    h = fetch("https://www.so.com/s?q=" + urllib.parse.quote(q))
    out = []
    for m in re.finditer(r'<li class="res-list[^"]*"[^>]*>(.*?)</li>', h, re.S):
        blk = m.group(0)
        tm = re.search(r'<h3[^>]*>(.*?)</h3>', blk, re.S)
        title = txt(tm.group(1)).replace("\n", " ") if tm else ""
        dm = re.search(r'data-mdurl="([^"]+)"', blk)
        link = html.unescape(dm.group(1)) if dm else ""
        sm = re.search(r'<p class="res-desc"[^>]*>(.*?)</p>', blk, re.S)
        snip = txt(sm.group(1)).replace("\n", " ") if sm else ""
        if title:
            out.append((title, snip, link))
        if len(out) >= n: break
    return out

if __name__ == "__main__":
    mode = sys.argv[1]
    if mode == "q":
        for i, (t, s, l) in enumerate(search(sys.argv[2], int(sys.argv[3]) if len(sys.argv) > 3 else 15), 1):
            print(f"[{i}] {t}\n    {s}\n    {l}")
    elif mode == "get":
        print(txt(fetch(sys.argv[2]))[:9000])
    elif mode == "getfull":
        print(txt(fetch(sys.argv[2]))[:30000])
